25	const oldSpecsDir = join(migrationsRoot, MIGRATIONS_OLD_SUBDIR);
26	export const isSpec = (f) => f.endsWith('.mjs') && !f.endsWith('.test.mjs');
27	const readSpecs = (d) => { try { return readdirSync(d).filter(isSpec).sort(); } catch { return []; } };
28	// Tolerant of an absent/empty folder — a vendored consumer, or a canon
29	// checkout after every record has retired.
30	export const specFiles = () => readSpecs(specsDir);
31	// The aged (archived) records — canon-only, so this is empty in any vendored
32	// consumer mount. Used by the APPLY/backfill path (registry.loadMigrations), NOT
33	// by check-tolerance: a migration's legacy tolerance ENDS when it ages out of
34	// active_migrations (all up-to-date repos converged within the TTL), while its
35	// apply logic persists here for a dormant project's backfill.
36	export const oldSpecFiles = () => readSpecs(oldSpecsDir);
