106	  for (const { file, replace } of migration.rewrite) {
107	    const text = await read(file);
108	    if (text == null) continue;
109	    let next = text;
110	    for (const { from, to } of replace ?? []) next = next.split(from).join(to);
111	    if (next !== text) { await write(file, next); done.push(file); }
112	  }
113	  return done;
