168	// project's backfill, never deleted. This guard stays for the legacy central
169	// routine (the rollback until Phase 4), but it now REFUSES to touch a record
170	// already archived in migrations-old (subdir), so the archiver and the legacy
171	// deleter can never fight over the same record.
172	export function retirableMigrations(migrations, { pending, unknownCount, today, appliedThisCycle = new Set() }) {
173	  if (unknownCount > 0) return [];
174	  return migrations.filter((m) => {
175	    if (m.subdir === MIGRATIONS_OLD_SUBDIR) return false; // archived for backfill — never fleet-deleted
176	    if ((m.retire ?? 'auto') !== 'auto') return false;
177	    if ((pending.get(m.id) ?? 0) > 0) return false;
178	    if (appliedThisCycle.has(m.id)) return false;
179	    return String(today) > String(m.landed);
