188	// evidence and no quiescence proof is needed. Only records currently in
189	// active_migrations are candidates (an already-archived record is skipped).
190	export function migrationsPastTtl(migrations, { today, ttlDays }) {
191	  const cutoff = new Date(`${today}T00:00:00Z`).getTime() - ttlDays * 86400000;
192	  return migrations.filter((m) => {
193	    if (m.subdir === MIGRATIONS_OLD_SUBDIR) return false; // already archived
